const projects=[...(window.TAMIRLAB_WORKSHOP_PROJECTS||[]),...(window.TAMIRLAB_HOME_REPAIRS||[])];
const featuredIds=['e01','r01','p01','s01','e13','r13','p14','s14'];
projects.sort((a,b)=>{const ai=featuredIds.indexOf(a.id),bi=featuredIds.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi)});
const tools=window.YenilikciLabTools;
const state={filter:'Tümü',search:'',expanded:false,favorites:new Set(tools.parseList('yenilikcilab-favorites')),completed:new Set(tools.parseList('yenilikcilab-completed'))};
const grid=document.getElementById('projectGrid');const empty=document.getElementById('emptyState');const toast=document.getElementById('toast');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cardMarkup(p){const done=state.completed.has(p.id);return `<article class="project-card ${done?'is-completed':''}" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(p.title)} rehberini aç"><div class="project-visual ${esc(p.visual)}"><span class="visual-orb"></span><span class="project-level">${esc(p.level)}</span><button class="project-fav ${state.favorites.has(p.id)?'is-fav':''}" data-fav="${esc(p.id)}" aria-label="${state.favorites.has(p.id)?'Favorilerden çıkar':'Favoriye ekle'}">${state.favorites.has(p.id)?'♥':'♡'}</button>${done?'<span class="project-completed-mark">✓ Tamamlandı</span>':''}<span class="project-emoji">${esc(p.emoji)}</span></div><div class="project-body"><div class="project-tags"><span class="project-tag ${p.tagType==='robotics'?'tag-robotics':p.tagType==='coding'?'tag-coding':p.tagType==='home'?'tag-home':''}">${esc(p.tag)}</span></div><h3 class="project-title">${esc(p.title)}</h3><p class="project-desc">${esc(p.description)}</p><div class="project-meta"><span>◷ ${esc(p.time)}</span><strong>${esc(p.difficulty)}</strong><span class="meta-arrow">↗</span></div></div></article>`}
function matches(p){const f=state.filter;const levelMatch=['İlkokul','Ortaokul','Lise'].includes(f)?p.level===f:true;const categoryMatch=['Elektronik','Robotik','Programlama','Evde Tamir'].includes(f)?p.category===f:f==='STEM'?p.category==='STEM':true;const statusMatch=f==='Favoriler'?state.favorites.has(p.id):f==='Tamamlananlar'?state.completed.has(p.id):true;const searchMatch=(p.title+' '+p.category+' '+p.level+' '+p.description+' '+p.tag+' '+(p.materials||[]).join(' ')).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr'));return levelMatch&&categoryMatch&&statusMatch&&searchMatch}
function render(){let list=projects.filter(matches);if(!state.expanded&&state.filter==='Tümü')list=list.slice(0,8);grid.innerHTML=list.map(cardMarkup).join('');empty.hidden=list.length>0;grid.hidden=list.length===0;const count=document.getElementById('catalogCount');if(count)count.textContent=`${projects.length} proje · ${state.completed.size} tamamlandı`;const favoritesCount=document.getElementById('favoritesCount'),completedCount=document.getElementById('completedCount');if(favoritesCount)favoritesCount.textContent=state.favorites.size;if(completedCount)completedCount.textContent=state.completed.size}
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2200)}
function projectDiagram(p){
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const spec=window.TAMIRLAB_PROJECT_DIAGRAMS&&window.TAMIRLAB_PROJECT_DIAGRAMS[p.id];
 return spec?renderProjectSchematic(p,spec,esc):repairDiagram(p,esc);
}
function diagramLines(value,max=20){const words=String(value).split(/\s+/),out=[];let line='';for(const word of words){if(line&&(line+' '+word).length>max){out.push(line);line=word}else line=(line+' '+word).trim()}if(line)out.push(line);return out.slice(0,3)}
function diagramText(value,x,y,max=20,cls='diagram-node-label'){return `<text x="${x}" y="${y}" text-anchor="middle" class="${cls}">${diagramLines(value,max).map((line,i)=>`<tspan x="${x}" dy="${i?15:0}">${esc(line)}</tspan>`).join('')}</text>`}
function renderProjectSchematic(p,d,esc){
 if(d.kind==='circuit')return renderCircuitSchematic(p,d,esc);
 if(d.kind==='mechanism')return renderMechanismSchematic(p,d,esc);
 if(d.kind==='program')return renderProgramSchematic(p,d,esc);
 if(d.kind==='experiment')return renderExperimentSchematic(p,d,esc);
 return repairDiagram(p,esc);
}
