function renderMechanismSchematic(p,d,esc){
 const parts=d.parts.map((part,i)=>{const x=122+i*238;return `<g><rect x="${x-93}" y="302" width="186" height="76" rx="12" fill="#fff" stroke="${['#ff665e','#7547ff','#16a99c','#efbd00'][i]}" stroke-width="2.5"/><circle cx="${x-68}" cy="320" r="9" fill="${['#ff665e','#7547ff','#16a99c','#efbd00'][i]}"/><text x="${x-68}" y="323" text-anchor="middle" class="diagram-number">${i+1}</text>${diagramText(part,x,340,21)}<text x="${x}" y="369" text-anchor="middle" class="diagram-note">${esc(d.links[i]||'mekanik bağ')}</text></g>${i<3?`<path d="M${x+94} 340 H${x+143} l-8 -7 m8 7 -8 7" class="diagram-arrow"/>`:''}`}).join('');
 return `<section class="modal-section diagram-section"><h3>Projeye özel mekanizma şeması</h3><p class="diagram-caption"><b>${esc(d.title)}</b> — parça yerleşimi ve kuvvet/hareket aktarımı.</p><div class="diagram-frame"><svg viewBox="0 0 960 410" role="img" aria-label="${esc(p.title)} için teknik mekanizma şeması"><defs><marker id="arrowCoral" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8Z" fill="#ff665e"/></marker><marker id="arrowPurple" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8Z" fill="#7547ff"/></marker><marker id="arrowTeal" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8Z" fill="#16a99c"/></marker></defs><rect x="1" y="1" width="958" height="408" rx="18" fill="#fbfaff" stroke="#e9e4f1"/><text x="34" y="34" class="diagram-label">${esc(d.layout.toLocaleUpperCase('tr'))} · MEKANİZMA / BAĞLANTI PLANI</text><g>${mechanismArt(d.layout)}</g><path d="M28 276 H932" stroke="#ddd8e8" stroke-width="2"/>${parts}<text x="34" y="399" class="diagram-note">Üstte mekanizma/yerleşim; altta parçaların bağlanma ve hareket sırası. Prototip sonucu yalnızca tamamlama ekranında görünür.</text></svg></div><p class="diagram-caption">${esc(d.note)}</p></section>`;
}
function renderProgramSchematic(p,d,esc){
 const n=d.nodes;const label=(text,x,y,max=24)=>diagramText(text,x,y,max,'diagram-node-label');
 const body=`<rect x="1" y="1" width="958" height="398" rx="18" fill="#fbfaff" stroke="#e9e4f1"/><text x="34" y="34" class="diagram-label">${esc(d.mode.toLocaleUpperCase('tr'))} · OLAY, KOŞUL VE ÇIKTI AKIŞI</text><rect x="38" y="94" width="188" height="86" rx="14" fill="#fff" stroke="#ff665e" stroke-width="3"/><text x="132" y="124" text-anchor="middle" class="diagram-component">GİRDİ</text>${label(n[0],132,150)}<path d="M226 137 H278" class="diagram-arrow"/><rect x="278" y="94" width="192" height="86" rx="14" fill="#f1edff" stroke="#7547ff" stroke-width="3"/><text x="374" y="124" text-anchor="middle" class="diagram-component">İŞLEM</text>${label(n[1],374,150)}<path d="M470 137 H508" class="diagram-arrow"/><path d="M590 77 L670 137 L590 197 L510 137Z" fill="#fff8d9" stroke="#efbd00" stroke-width="3"/>${label(d.condition,590,132,25)}<text x="590" y="157" text-anchor="middle" class="diagram-note">koşul</text><path d="M670 137 H727" class="diagram-arrow"/><text x="697" y="124" class="diagram-note">EVET</text><rect x="727" y="94" width="194" height="86" rx="14" fill="#e9faf6" stroke="#16a99c" stroke-width="3"/><text x="824" y="124" text-anchor="middle" class="diagram-component">SONUÇ</text>${label(n[2]+' → '+n[3],824,150,27)}${d.mode==='loop'?`<path d="M590 197 V247 H374 V180" fill="none" stroke="#ff665e" stroke-width="3" stroke-dasharray="7 6"/><text x="480" y="241" class="diagram-note">HAYIR → döngünün sonraki turu</text>`:`<path d="M590 197 V247 H374 V180" fill="none" stroke="#ff665e" stroke-width="3" stroke-dasharray="7 6"/><text x="480" y="241" class="diagram-note">HAYIR → alternatif / düzeltme yolu</text>`}<rect x="36" y="286" width="886" height="79" rx="12" fill="#30283e"/><text x="58" y="313" fill="#d8ccff" font-size="11" font-weight="800">PSEUDOCODE</text><text x="58" y="343" fill="#fff" font-size="13" font-family="monospace">${esc(d.code)}</text>`;
 return `<section class="modal-section diagram-section"><h3>Projeye özel algoritma şeması</h3><p class="diagram-caption"><b>${esc(d.title)}</b></p><div class="diagram-frame"><svg viewBox="0 0 960 400" role="img" aria-label="${esc(p.title)} için karar dallı algoritma"><g>${body}</g></svg></div><p class="diagram-caption">${esc(d.note||'Kodlamadan önce akışı örnek veriyle elle izle; yanlış dalı ve beklenen çıktıyı proje defterine yaz.')}</p></section>`;
}
