function stemPrototypeArt(p){
 const d=window.TAMIRLAB_PROJECT_DIAGRAMS?.[p.id];if(!d)return `<text x="400" y="150" text-anchor="middle" class="proto-caption">${esc(p.title)}</text>`;
 return `<g transform="translate(130 20) scale(.72)">${experimentArt(d.apparatus)}</g><rect x="190" y="240" width="420" height="34" rx="17" fill="#fff" stroke="#16a99c" stroke-width="2"/><text x="400" y="262" text-anchor="middle" class="proto-caption">${esc(p.title)}</text>`;
}
function projectPrototype(p){
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let art='';
 if(p.id==='e01'){
  art=`<rect x="152" y="36" width="296" height="220" rx="22" fill="#fffdf3" stroke="#ff665e" stroke-width="4"/><path d="M177 88 H423 M177 205 H423" stroke="#19aaa0" stroke-width="5" stroke-dasharray="7 5"/><circle cx="198" cy="88" r="12" fill="#ff665e"/><circle cx="580" cy="88" r="12" fill="#efbd00"/><circle cx="198" cy="205" r="12" fill="#7547ff"/><circle cx="580" cy="205" r="12" fill="#23b879"/><circle cx="198" cy="88" r="23" fill="#ff665e" opacity=".14"/><circle cx="580" cy="88" r="23" fill="#efbd00" opacity=".17"/><text x="300" y="153" text-anchor="middle" class="proto-name">YENİLİKÇİLAB</text><text x="300" y="181" text-anchor="middle" class="proto-sub">IŞIKLI İSİM KARTI</text><path d="M120 78 h25 M120 218 h25 M455 78 h25 M455 218 h25" stroke="#7547ff" stroke-width="4" stroke-linecap="round"/>`;
 }else if(p.category==='Elektronik'){
  art=electronicsPrototypeArt(p);
 }else if(p.category==='Robotik'){
  art=robotPrototypeArt(p);
 }else if(p.category==='Programlama'){
  art=programmingPrototypeArt(p);
 }else if(p.category==='STEM'){
  art=stemPrototypeArt(p);
 }else{
  art=`<rect x="200" y="80" width="400" height="155" rx="24" fill="#fff" stroke="#dcd6e8" stroke-width="4"/><text x="400" y="162" text-anchor="middle" class="proto-emoji">${esc(p.emoji||'🧰')}</text><circle cx="577" cy="83" r="38" fill="#e8f8e6"/><path d="M558 83 L571 97 L598 68" fill="none" stroke="#39a331" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><text x="400" y="218" text-anchor="middle" class="proto-caption">GÜVENLİ BAKIM SONUCU</text>`;
 }
 return `<figure class="prototype-preview"><div class="prototype-heading"><span>ÖRNEK PROTOTİP</span><small>Beklenen sonuç</small></div><div class="prototype-frame"><svg viewBox="0 0 800 300" role="img" aria-label="${esc(p.title)} için örnek tamamlanmış prototip"><rect x="1" y="1" width="798" height="298" rx="22" fill="#fbfaff" stroke="#e9e4f1"/>${art}</svg></div><figcaption>${esc(p.title)} · Örnek çizim; kullanılan malzemeye ve tasarıma göre görünüm değişebilir.</figcaption></figure>`;
}
function renderGuideComplete(p){
 const host=document.getElementById('modalContent');
 state.completed.add(p.id);tools.storeList('yenilikcilab-completed',state.completed);render();
 host.innerHTML=`<div class="guide-complete"><div class="guide-complete-mark">✓</div><span class="section-kicker">GÜZEL İŞ!</span><h2 class="guide-title" id="modalTitle">${esc(p.title)}</h2>${projectPrototype(p)}<p>Proje adımlarını tamamladın. Neyi öğrendiğini ve bir sonraki denemede neyi değiştireceğini proje defterine not et.</p><div class="guide-photo" id="guidePhoto"><h3>Kendi prototipinin fotoğrafı</h3><p>Fotoğraf yalnızca bu cihazda saklanır; sunucuya gönderilmez. İstersen ekleyebilir, daha sonra silebilirsin.</p><div id="guidePhotoPreview"></div><div class="guide-photo-controls"><label for="guidePhotoInput">Fotoğraf seç</label><input id="guidePhotoInput" type="file" accept="image/*"><button type="button" id="removeGuidePhoto" hidden>Fotoğrafı sil</button><span class="guide-photo-status" id="guidePhotoStatus" aria-live="polite"></span></div></div><div class="guide-actions"><button class="button button-outline" id="guideRepeat">Rehberi yeniden aç</button><button class="button button-dark" id="guideDone">Kapat</button></div></div>`;
 showSavedPhoto(p.id);
 document.getElementById('guidePhotoInput').addEventListener('change',async e=>{const file=e.target.files&&e.target.files[0];if(!file)return;const status=document.getElementById('guidePhotoStatus');status.textContent='Fotoğraf hazırlanıyor…';try{await tools.savePhoto(p.id,file);await showSavedPhoto(p.id);status.textContent='Fotoğraf bu cihazda saklandı.'}catch(error){status.textContent=error.message||'Fotoğraf saklanamadı.'}e.target.value=''});
 document.getElementById('removeGuidePhoto').addEventListener('click',async()=>{try{await tools.removePhoto(p.id);await showSavedPhoto(p.id);document.getElementById('guidePhotoStatus').textContent='Fotoğraf cihazdan silindi.'}catch(_){document.getElementById('guidePhotoStatus').textContent='Fotoğraf silinemedi.'}});
 document.getElementById('guideRepeat').addEventListener('click',()=>renderGuideSetup(p));
 document.getElementById('guideDone').addEventListener('click',()=>{document.getElementById('modalBackdrop').hidden=true;document.body.style.overflow=''});
}
async function showSavedPhoto(id){const holder=document.getElementById('guidePhotoPreview'),remove=document.getElementById('removeGuidePhoto');if(!holder||!remove)return;try{const item=await tools.getPhoto(id);if(item&&item.dataUrl){holder.innerHTML=`<img src="${esc(item.dataUrl)}" alt="Seçilen prototip fotoğrafı">`;remove.hidden=false}else{holder.textContent='';remove.hidden=true}}catch(_){holder.textContent='Bu cihazda fotoğraf saklama kullanılamıyor.';remove.hidden=true}}
function toggleFavorite(id){if(state.favorites.has(id)){state.favorites.delete(id);showToast('Favorilerden çıkarıldı.')}else{state.favorites.add(id);showToast('Favorilerine eklendi.')}tools.storeList('yenilikcilab-favorites',state.favorites);render()}
function setFilter(filter){document.querySelectorAll('.filter-chip').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));state.filter=filter;state.expanded=filter!=='Tümü';render()}
grid.addEventListener('click',e=>{const fav=e.target.closest('[data-fav]');if(fav){e.stopPropagation();toggleFavorite(fav.dataset.fav);return}const card=e.target.closest('[data-id]');if(card)openProject(card.dataset.id)});grid.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.project-card')){e.preventDefault();openProject(e.target.dataset.id)}});
document.querySelectorAll('.filter-chip').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));
document.getElementById('projectSearch').addEventListener('input',e=>{state.search=e.target.value;render()});document.getElementById('modalClose').addEventListener('click',()=>{document.getElementById('modalBackdrop').hidden=true;document.body.style.overflow=''});document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop'){e.currentTarget.hidden=true;document.body.style.overflow=''}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('modalBackdrop').hidden=true;document.body.style.overflow=''}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.getElementById('projectSearch').focus()}});
document.querySelectorAll('.workshop-card').forEach(a=>a.addEventListener('click',()=>{setFilter(a.dataset.category);state.expanded=true;render()}));
document.querySelector('.feature-copy .button-coral').addEventListener('click',()=>{setFilter('Evde Tamir');state.expanded=true;render()});
document.querySelector('.menu-toggle').addEventListener('click',()=>document.querySelector('.desktop-nav').classList.toggle('open'));document.querySelectorAll('.desktop-nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.desktop-nav').classList.remove('open')));document.querySelector('.search-open').addEventListener('click',()=>{document.getElementById('projectSearch').focus();document.getElementById('projeler').scrollIntoView({behavior:'smooth'})});
render();
